from pathlib import Path
root=Path(__file__).resolve().parents[1];directory=root/'research/knot-classifier';path=directory/'lattice-blind-benchmark.json';data=json.loads(path.read_text());audit=json.loads((directory/'lattice-blind-verification.json').read_text())
assert audit['verified'];data['independentVerification']=audit;path.write_text(json.dumps(data)+'\n');lanes={r['lane']:r for r in data['lanes']};summaries={r['lane']:r for r in audit['lanes']};marked=lanes['marked'];brute=lanes['brute'];stats=summaries['marked']['stats']
